def min_length(pw):
    return len(pw) >= 8

def has_upper(pw):
    return any(c.isupper() for c in pw)

RULES = [min_length, has_upper]

def is_valid(pw, rules=RULES):
    return all(rule(pw) for rule in rules)

print(is_valid("Secret12"))

class Account:
    def __init__(self, balance):
        self.balance = balance
    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("insufficient funds")
        self.balance -= amount
class LimitedAccount(Account):
    def withdraw(self, amount):
        if amount > 100:
            raise ValueError("limit is 100")
        super().withdraw(amount)

class OrderService {
    private final MySqlOrderRepository repo = new MySqlOrderRepository();

    double total(int customerId) {
        double sum = 0;
        for (Order o : repo.findByCustomer(customerId)) sum += o.amount();
        return sum;
    }
}

class Inbox:
    def __init__(self, messages):
        self.messages = messages

    def has_unread(self):
        unread = [m for m in self.messages if not m["read"]]
        for m in unread:
            m["read"] = True
        return len(unread) > 0

box = Inbox([{"read": False}])
print(box.has_unread(), box.has_unread())
